'use client';

import * as React from 'react';
import {createComponent} from '@lit/react';
import '@material/web/labs/gb/components/tabs/md-gb-tab.js';
import '@material/web/labs/gb/components/tabs/md-gb-tab-panels.js';
import '@material/web/labs/gb/components/tabs/md-gb-tabs.js';
import {TabElement} from '@material/web/labs/gb/components/tabs/tab-element.js';
import {TabPanelsElement} from '@material/web/labs/gb/components/tabs/tab-panels-element.js';
import {TabsElement} from '@material/web/labs/gb/components/tabs/tabs-element.js';

/**
 * A Material Design tab component. Wraps <md-gb-tab>.
 * Docs: https://material-web.dev/3.0/components/tabs/
 */
export const MdTab = createComponent({
  react: React,
  tagName: 'md-gb-tab',
  elementClass: TabElement,
});

export type MdTabProps = React.ComponentProps<typeof MdTab>;

/**
 * The swipeable content panels of a set of Material Design tabs. Wraps <md-gb-tab-panels>.
 * Docs: https://material-web.dev/3.0/components/tabs/
 */
export const MdTabPanels = createComponent({
  react: React,
  tagName: 'md-gb-tab-panels',
  elementClass: TabPanelsElement,
});

export type MdTabPanelsProps = React.ComponentProps<typeof MdTabPanels>;

/**
 * A Material Design tabs component. Wraps <md-gb-tabs>.
 * Docs: https://material-web.dev/3.0/components/tabs/
 */
export const MdTabs = createComponent({
  react: React,
  tagName: 'md-gb-tabs',
  elementClass: TabsElement,
});

export type MdTabsProps = React.ComponentProps<typeof MdTabs>;
